/* WahalaVerse MVP — framework-free, mobile-first, with optional Supabase sync.
   Built for sharing without requiring accounts. See README.md before going public. */
(() => {
'use strict';
// Shared pure logic/content lives in core.js (also used by the Node test suite).
const C = window.WahalaCore;
const {Q, DEMO, SCENES, SIM_START} = C;
const encodeChallenge = C.encodeChallenge;
const decodeChallenge = C.decodeChallenge;
// Assume Their Life — role-agnostic causal engine (atl-engine.js) + the first
// playable role pack (atl-pack-afrobeats.js). Both load before app.js.
const ATL = window.WahalaATL;
// Assume Their Life role packs. Founder Life first (active core scope); Afrobeats is
// an additional role. CEO / Billionaire / Political register here as they are built.
const ATL_PACKS = [['founder', window.WAHALA_ATL_FOUNDER], ['ceo', window.WAHALA_ATL_CEO], ['billionaire', window.WAHALA_ATL_BILLIONAIRE], ['political', window.WAHALA_ATL_POLITICAL], ['afrobeats', window.WAHALA_ATL_AFROBEATS]].filter(x => x[1]);
const curPack = () => (ATL_PACKS.find(x => x[0] === state.atlRole) || [])[1] || null;
const root = document.getElementById('app');
const state = {page:'home',authOpen:false,supabase:null,cloudReady:false,user:null,profile:null,
  loading:false,createName:'',createAnswers:Array(Q.length).fill(null),challenge:null,playAnswers:[],playStep:0,playSaved:false,
  createdUrl:'',createdCloud:false,creating:false,cloudLinkUnavailable:false,simIndex:0,simMoney:SIM_START.money,simPeace:SIM_START.peace,simStreet:SIM_START.street,simResponse:'',simDone:false,
  cloudActivities:[],cloudChallenges:[],loadingAccount:false,authEpoch:0,atlRole:null,atlRun:null,atlReaction:'',atlSaved:false,
  customName:'',customQuestions:null,customPreview:false,createdKind:'quick',ccRecovered:false};
// Fresh blank custom-challenge draft: the minimum (3) questions, 2 options each.
function blankCustom(){return Array.from({length:C.CUSTOM_LIMITS.minQuestions},()=>({q:'',a:['',''],answer:null}))}
// --- Create Your Own Wahala: device-local draft autosave (wv_cc_draft) --------
const CC_DRAFT_KEY='wv_cc_draft';
let ccSaveTimer=null;        // pending debounced write
let ccSuppressSave=false;    // set when a draft is discarded/generated so a stray
                             // in-flight save can't resurrect it (re-enabled on next edit)
function saveCcDraftNow(){
  if(ccSuppressSave)return;
  if(state.page!=='create-custom')return;
  if(state.createdUrl&&state.createdKind==='custom')return;          // already generated
  const name=state.customName||'',questions=state.customQuestions||[];
  if(!C.isMeaningfulCustomDraft(name,questions))return;              // skip pristine blank
  try{localStorage.setItem(CC_DRAFT_KEY,JSON.stringify({v:C.CC_DRAFT_VERSION,name,questions,savedAt:Date.now()}))}
  catch{/* quota exceeded / private mode: autosave is best-effort */}
}
function scheduleCcSave(){ccSuppressSave=false;clearTimeout(ccSaveTimer);ccSaveTimer=setTimeout(saveCcDraftNow,400)}
function clearCcDraft(){ccSuppressSave=true;clearTimeout(ccSaveTimer);try{localStorage.removeItem(CC_DRAFT_KEY)}catch{/* private mode */}}
function loadCcDraft(){try{const raw=localStorage.getItem(CC_DRAFT_KEY);if(!raw||raw.length>20000)return null;return C.sanitizeCustomDraft(JSON.parse(raw))}catch{return null}}
// Populate the builder from a saved draft (flagging recovery) or a blank form.
function ensureCustomDraft(){if(state.customQuestions)return;const d=loadCcDraft();if(d){state.customName=d.name;state.customQuestions=d.questions;state.ccRecovered=true}else{state.customQuestions=blankCustom();state.ccRecovered=false}}
const e = C.escapeHtml;
const titleCase = C.titleCase;
const formatted = C.formatNaira;
let qs = new URLSearchParams(location.search);
const cfg = window.WAHALA_CONFIG || {};
const hasConfig = Boolean(cfg.supabaseUrl && cfg.supabasePublishableKey);
const id = () => (globalThis.crypto?.randomUUID?.() || '00000000-0000-4000-8000-'+Math.random().toString(16).slice(2,14).padEnd(12,'0'));
const urlFor = params => (location.protocol==='file:'?location.href.split(/[?#]/)[0]:location.origin+location.pathname)+'?'+new URLSearchParams(params).toString();
function getRecent(){try{const raw = JSON.parse(localStorage.getItem('wv_activity')||'[]');return Array.isArray(raw)?raw.slice(0,60):[]}catch{return []}}
function setRecent(data){try{localStorage.setItem('wv_activity',JSON.stringify(data.slice(0,60)))}catch{/* private mode */}}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3100)}
function nav(page,params){state.page=page;state.authOpen=false;let path=location.pathname; if(params)path+='?'+new URLSearchParams(params).toString();else if(page!=='home')path+='?page='+page;history.pushState({},'',path);window.scrollTo({top:0,behavior:'instant'});render();}
function header(){const isActive=p=>state.page===p?'active':'';const cur=p=>state.page===p?' aria-current="page"':'';const display=state.user?(state.profile?.display_name||state.user.user_metadata?.display_name||'My corner'):'Join the cruise';return `
<header class="topbar"><div class="shell navinner"><a href="${e(location.pathname)}" class="logo" data-action="nav" data-page="home"><span class="logo-icon">⚡</span><span>Wahala<em>Verse.</em></span></a>
<nav class="toplinks" aria-label="Main navigation"><a class="navlink ${isActive('home')}" href="?page=home" data-action="nav" data-page="home"${cur('home')}>Explore</a><a class="navlink ${isActive('create')}" href="?page=create" data-action="nav" data-page="create"${cur('create')}>Make a challenge</a><a class="navlink ${isActive('sim')}" href="?page=sim" data-action="nav" data-page="sim"${cur('sim')}>Life simulator</a><a class="navlink ${isActive('atl')}" href="?page=atl" data-action="nav" data-page="atl"${cur('atl')}>Assume a life</a><a class="navlink ${isActive('account')}" href="?page=account" data-action="nav" data-page="account"${cur('account')}>My corner</a></nav>
<button class="button small ${state.user?'secondary':'primary'}" data-action="${state.user?'nav':'auth'}" ${state.user?'data-page="account"':''}>${state.user?'👤 '+e(display):'Join the cruise ↗'}</button></div></header>`}
function footer(){return `<footer class="shell footer"><div>© ${new Date().getFullYear()} WahalaVerse • Made for cruise, built for vibes 🇳🇬</div><div><a href="privacy.html" target="_blank" rel="noopener">Privacy & data</a> · <span>${state.cloudReady?'☁ Cloud account mode':'⚡ Guest demo mode'}</span></div></footer>`}
function bottomNav(){const items=[['home','⌂','Explore'],['create','⊕','Create'],['sim','🎮','Survive'],['account','☻','Me']];return `<nav class="bottom-nav" aria-label="Mobile navigation">${items.map(([page,ico,label])=>`<button data-action="nav" data-page="${page}" class="${state.page===page?'active':''}"${state.page===page?' aria-current="page"':''}><span class="navico" aria-hidden="true">${ico}</span><span>${label}</span></button>`).join('')}</nav>`}
function home(){return `<main class="shell"><section class="hero"><div><span class="pill"><i></i> Nigerian cruise, unlimited</span><h1>Catch cruise.<br><span class="accent">Not feelings.</span> 😌</h1><p class="intro">Your friends claim they know you. Your life claims you're financially responsible. <strong style="color:#fff">Time to find out who's lying.</strong></p><div class="hero-btns"><button class="button primary" data-action="nav" data-page="create">Make your challenge ↗</button><button class="button secondary" data-action="sample">Try one first ▶</button></div><div class="hero-micro"><span>✨ No download</span><span>📱 Built for your phone</span><span>💬 Share on WhatsApp</span></div></div>
<div class="preview-tilt"><div class="preview-card"><span class="label">🔥 Today's main gist</span><h2>How well do your people <i>really</i> know you?</h2><p>7 outrageous questions. One friendship score. Many dramatic reactions.</p><div class="preview-art"><span class="tag-sticker">ARE YOU SURE? 👀</span><span class="face">😏</span><span class="tag-sticker second-sticker">7/7 OR WE FIGHT!</span></div><div class="preview-bottom"><span>FRIENDSHIP CHALLENGE</span><span>↗</span></div></div></div></section>
<section class="section"><div class="sectionhead"><div><span class="kicker">The playground</span><h2>Pick your kind of wahala.</h2></div><p>Fast games, messy decisions and stories made for your group chat.</p></div><div class="cards">
<article class="experience"><div class="eyebrow">01 · Live now</div><span class="card-emoji">🫂</span><h3>Predict My Wahala</h3><p>Choose what you would do. Challenge your people to guess your answers.</p><button class="button small primary" data-action="nav" data-page="create">Make a challenge ↗</button></article>
<article class="experience"><div class="eyebrow">02 · Live now</div><span class="card-emoji">💸</span><h3>Survive Naija</h3><p>Salary, family, transport and temptation. Can your account survive the month?</p><button class="button small secondary" data-action="nav" data-page="sim">Start surviving ↗</button></article>
<article class="experience"><div class="eyebrow">03 · Live now</div><span class="card-emoji">✍️</span><h3>Create Your Own Wahala</h3><p>Write your own questions and options. Share the link; your people try to guess you.</p><button class="button small primary" data-action="nav" data-page="create-custom">Create your own ↗</button></article>
<article class="experience"><div class="eyebrow">04 · New</div><span class="card-emoji">🎭</span><h3>Assume Their Life</h3><p>Step into a founder, CEO, billionaire, governor or star — a whole life. Make real decisions across a year and live with the consequences.</p><button class="button small primary" data-action="nav" data-page="atl">Assume a life ↗</button></article></div></section>
<section class="section"><div class="sectionhead"><div><span class="kicker">Simple as 1 · 2 · 3</span><h2>You're the main character.</h2></div></div><div class="steps"><div class="step"><span class="step-number">01 /</span><h3>Pick your answers</h3><p>Seven classic Nigerian what-would-you-do moments. No essays, abeg.</p></div><div class="step"><span class="step-number">02 /</span><h3>Drop the link</h3><p>Send your challenge to WhatsApp, your group chat or that one friend.</p></div><div class="step"><span class="step-number">03 /</span><h3>Watch the scores</h3><p>Each friend gets a hilarious result and can make their own challenge.</p></div></div></section>
<section class="section"><div class="banner"><div><h2>Your people think they know you?</h2><p>Let's see how brave they are. Create a challenge in under two minutes.</p></div><button class="button" data-action="nav" data-page="create">Challenge them ↗</button></div></section></main>`}
function create(){if(state.createdUrl)return created();return `<main class="shell page"><div class="page-header"><span class="kicker">The friendship experiment 🧪</span><h1>Predict My <span class="accent">Wahala.</span></h1><p>Tell us what you'd do in seven ridiculous situations. Your friends get a link to guess your answers. No account required to try.</p></div><div class="content-grid"><section class="panel"><div class="field"><label for="creator-name">Your display name</label><input id="creator-name" name="creator-name" maxlength="30" placeholder="e.g. Tola the menace 😭" value="${e(state.createName||state.profile?.display_name||'')}" autocomplete="nickname"><div class="helper">Shown to anyone with your challenge link. Don't use private details.</div></div><div id="creator-questions">${Q.map((q,i)=>`<section class="question"><span class="question-index">Question ${String(i+1).padStart(2,'0')} of 07</span><h3>${e(C.renderSubject(q.q, state.createName||'', 'self'))}</h3><div class="options">${q.a.map((ans,j)=>`<button type="button" class="option ${state.createAnswers[i]===j?'selected':''}" data-action="create-option" data-q="${i}" data-answer="${j}" aria-pressed="${state.createAnswers[i]===j}"><span class="letter">${String.fromCharCode(65+j)}</span>${e(ans)}</button>`).join('')}</div></section>`).join('')}</div><div class="countbox"><span><span id="answered-count">${state.createAnswers.filter(x=>x!==null).length}</span> / ${Q.length} answered</span><div class="progress"><div class="progress-fill" id="create-progress" style="width:${state.createAnswers.filter(x=>x!==null).length/Q.length*100}%"></div></div></div><button class="button primary block" data-action="create-save">Generate my challenge link ↗</button></section><aside class="side-panel"><div class="pill hot">🌶️ The rules</div><h3 style="margin-top:19px">No wrong answers.</h3><p>Except maybe the one about sending ₦500k back. We don't judge. Much.</p><div class="callout"><b>Why your friends will share:</b><br>They score themselves, drag you in the group chat, then make their own version.</div><p style="margin-top:19px">${state.user?'☁ You are signed in. Your challenge will be saved to your account.':'⚡ Guest links work without an account. Sign in to save them across devices.'}</p>${!state.user?'<button class="button secondary small" data-action="auth">Sign in to save</button>':''}</aside></div></main>`}
function created(){const link=state.createdUrl;return `<main class="shell page"><div class="page-header"><span class="kicker">Challenge created ✅</span><h1>Wahala has been <span class="accent">unlocked.</span></h1><p>That was easy. Now find out who your real friends are. Send this link everywhere.</p></div><div class="content-grid"><section class="panel"><div class="result-hero"><div class="result-emoji">🎉</div><h2>Your challenge is ready!</h2><p>Seven questions. One link. Potential group-chat chaos.</p></div><div class="sharebox" id="share-link">${e(link)}</div><div class="share-actions"><button class="button primary" data-action="share-link">Share challenge ↗</button><button class="button secondary" data-action="copy-link">Copy link 📋</button><button class="button ghost" data-action="test-link">Preview the game</button></div><p style="font-size:12px;margin:20px 0 0">${state.createdCloud?'☁ Saved to your WahalaVerse account.':'⚡ Guest link: your name, questions and answers are encoded in the link. Keep it if you want to share again.'}</p></section><aside class="side-panel"><h3>What's next?</h3><p>Post the link on WhatsApp Status with “If you score below half, I no know you” 😭</p><button class="button block secondary" data-action="reset-create">Make another challenge</button></aside></div></main>`}
function ccReady(){const L=C.CUSTOM_LIMITS;const qs=state.customQuestions||[];const per=qs.map(q=>{const opts=(q.a||[]).map(o=>(o||'').trim());const filled=opts.filter(Boolean).length;const ansOk=q.answer!=null&&opts[q.answer]&&opts[q.answer].length>0;return (q.q||'').trim().length>0&&filled>=L.minOptions&&q.a.every(o=>(o||'').trim().length>0)&&ansOk});const nameOk=(state.customName||'').trim().length>=2;const countOk=qs.length>=L.minQuestions&&qs.length<=L.maxQuestions;return {per,completeCount:per.filter(Boolean).length,allReady:nameOk&&countOk&&per.length>0&&per.every(Boolean)}}
function createCustom(){ensureCustomDraft();if(state.createdUrl&&state.createdKind==='custom')return created();if(state.customPreview)return customPreview();const L=C.CUSTOM_LIMITS,qs=state.customQuestions,r=ccReady();const inStyle='display:block;width:100%;border:1px solid #45445e;background:#141425;padding:12px 14px;border-radius:12px;color:#fff;font-size:16px';return `<main class="shell page"><div class="page-header"><span class="kicker">Create Your Own Wahala ✍️</span><h1>Write your <span class="accent">own wahala.</span></h1><p>Set your questions, add the options, and tap the answer YOU would pick. Your friends try to guess you — no account needed.</p></div><div class="content-grid"><section class="panel">${state.ccRecovered?`<div class="callout" style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px"><span>↩ Recovered your unsaved draft.</span><span style="display:flex;gap:8px;flex:0 0 auto"><button type="button" class="button ghost small" data-action="cc-discard-draft">Start fresh</button><button type="button" class="button text" data-action="cc-dismiss-recovered" aria-label="Dismiss notice">✕</button></span></div>`:''}<div class="field"><label for="cc-name">Your display name</label><input id="cc-name" data-cc="name" maxlength="${L.nameLen}" placeholder="e.g. Tola the menace 😭" value="${e(state.customName)}" autocomplete="nickname"><div class="helper">Shown on your challenge link. It's encoded in the link, so don't use private info.</div></div>${qs.map((q,qi)=>`<section class="question"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><span class="question-index">Question ${qi+1} of ${qs.length} ${r.per[qi]?'✓':''}</span>${qs.length>L.minQuestions?`<button type="button" class="button text" data-action="cc-del-q" data-qi="${qi}" aria-label="Remove question ${qi+1}">Remove ✕</button>`:''}</div><input data-cc="q" data-qi="${qi}" maxlength="${L.questionLen}" placeholder="Type your question…" value="${e(q.q)}" aria-label="Question ${qi+1} text" style="${inStyle};margin:8px 0 6px"><div class="cc-suggest" data-qi="${qi}" style="color:#d1a000;margin:0 0 8px;font-size:12px;line-height:1.5;display:${(C.hasAmbiguousPerspective(q.q)&&!q.pAck)?'block':'none'}">🫶 This still says “you/my” — friends are guessing about <b>you</b>, not themselves. <button type="button" class="button text" data-action="cc-usename" data-qi="${qi}">Use my name</button> · <button type="button" class="button text" data-action="cc-ack" data-qi="${qi}">Keep as-is (intentional)</button></div><div class="options">${q.a.map((opt,oi)=>`<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px"><button type="button" class="option ${q.answer===oi?'selected':''}" data-action="cc-answer" data-qi="${qi}" data-oi="${oi}" aria-pressed="${q.answer===oi}" title="Mark as your answer" style="flex:0 0 auto;width:46px;height:46px;padding:0;justify-content:center"><span class="letter" style="margin:0">${String.fromCharCode(65+oi)}</span></button><input data-cc="o" data-qi="${qi}" data-oi="${oi}" maxlength="${L.optionLen}" placeholder="Option ${oi+1}" value="${e(opt)}" aria-label="Question ${qi+1} option ${oi+1}" style="${inStyle};flex:1">${q.a.length>L.minOptions?`<button type="button" class="button ghost small" data-action="cc-del-opt" data-qi="${qi}" data-oi="${oi}" aria-label="Remove option ${oi+1}" style="flex:0 0 auto">✕</button>`:''}</div>`).join('')}</div>${q.a.length<L.maxOptions?`<button type="button" class="button secondary small" data-action="cc-add-opt" data-qi="${qi}">+ Add option</button>`:''}<div class="helper" style="margin-top:8px">Tap a letter to mark the answer you'd pick. Tip: friends predict <b>you</b>, so refer to yourself by name — the "Use my name" button appears on any question that says "you/my".</div></section>`).join('')}${qs.length<L.maxQuestions?`<button type="button" class="button secondary block" data-action="cc-add-q" style="margin-top:6px">+ Add question (${qs.length}/${L.maxQuestions})</button>`:''}<div class="countbox" style="margin-top:16px"><span>${r.completeCount} / ${qs.length} questions ready</span><div class="progress"><div class="progress-fill" style="width:${qs.length?r.completeCount/qs.length*100:0}%"></div></div></div><button class="button primary block" data-action="cc-preview" ${r.allReady?'':'disabled'} style="margin-top:12px">Preview challenge ↗</button>${!r.allReady?`<div class="helper" style="margin-top:8px">Add your name and fill every question with ${L.minOptions}–${L.maxOptions} options and a marked answer to continue.</div>`:''}</section><aside class="side-panel"><div class="pill hot">✍️ Your rules</div><h3 style="margin-top:19px">${L.minQuestions}–${L.maxQuestions} questions · ${L.minOptions}–${L.maxOptions} options.</h3><p>Keep questions short and funny. The option you mark is the "correct" one your friends try to guess.</p><div class="callout">Everything is encoded in the share link — no login, no server. Don't include private or other people's personal info.</div></aside></div></main>`}
function customPreview(){const qs=state.customQuestions,name=titleCase(state.customName)||'You';const anyAmbig=qs.some(q=>C.hasAmbiguousPerspective(q.q)&&!q.pAck);return `<main class="shell page"><div class="page-header"><span class="kicker">Preview · ${e(name)}'s wahala 👀</span><h1>Looking <span class="accent">good?</span></h1><p>This is what your friends will play. Confirm the answers you marked, then generate your link.</p></div><div class="content-grid"><section class="panel">${anyAmbig?`<div class="callout" style="margin-bottom:14px">👀 Some questions still say "you" / "my". This is <b>exactly</b> what your friends will see — read each one and make sure it's clear it's about <b>${e(name)}</b>. Go back to edit if any reads like it's about the player.</div>`:''}${qs.map((q,qi)=>`<div class="question"><div class="question-index">Question ${qi+1}</div><h3 style="margin:8px 0 12px">${e(C.fillName(q.q,name))}</h3><div class="options">${q.a.map((opt,oi)=>`<div class="option ${q.answer===oi?'selected':''}" style="cursor:default"><span class="letter">${String.fromCharCode(65+oi)}</span>${e(C.fillName(opt,name))}${q.answer===oi?' — ✓ your pick':''}</div>`).join('')}</div></div>`).join('')}<div class="share-actions" style="margin-top:18px"><button class="button primary" data-action="cc-generate">Generate share link ↗</button><button class="button secondary" data-action="cc-back-edit">← Back to edit</button></div></section><aside class="side-panel"><h3>Last check 🔍</h3><p>Once you share the link, the questions and your marked answers travel inside it. You can still edit now.</p></aside></div></main>`}
// Recipient-facing wording: built-in (v1) questions render about the creator by name;
// creator-authored (v2) text only substitutes an explicit {name} placeholder.
function recipientQ(text,ch){return ch.questions?C.fillName(text,ch.owner_name):C.renderSubject(text,ch.owner_name,'other')}
function recipientOpt(text,ch){return ch.questions?C.fillName(text,ch.owner_name):text}
function player(){const ch=state.challenge;if(state.loading)return `<main class="shell page"><div class="panel" aria-busy="true"><h2>Loading challenge…</h2><p>Opening this WahalaVerse challenge for you 👀</p></div></main>`;if(state.cloudLinkUnavailable)return `<main class="shell page"><div class="panel"><h2>This shared link needs the cloud ☁️</h2><p>This link points to a saved (cloud) challenge, but this site isn't connected to a backend yet. Ask the creator for a guest link, or make your own.</p><button class="button primary" data-action="nav" data-page="create">Make your own challenge ↗</button></div></main>`;if(!ch)return `<main class="shell page"><div class="panel"><h2>This challenge couldn't load 😭</h2><p>The link may be broken, or the challenge was removed.</p><button class="button primary" data-action="nav" data-page="home">Return home</button></div></main>`;const QS=ch.questions||Q;const total=QS.length;const complete=state.playStep>=total;if(complete){const score=C.scoreQuiz(state.playAnswers,ch.answers);const pct=total?score/total:0;const [emoji,heading,description]=pct>=0.85?['🏆','Real one, confirmed!','You know this person suspiciously well. Omo, the friendship strong die. 🔥']:pct>=0.5?['😎','You sabi small!','Not bad at all — but your person still get plenty secrets for you. 👀']:['😭','Certified village person','Do you really know this human being? You get plenty explaining to do o. 😭'];return `<main class="shell page"><div class="page-header"><span class="kicker">Official friendship report</span><h1>The results are <span class="accent">in.</span></h1></div><div class="content-grid"><section class="panel"><div class="result-hero"><div class="result-emoji">${emoji}</div><div class="result-number">${score}<small style="font-size:.4em;color:#9b95b0">/${total}</small></div><h2>${heading}</h2><p>${description}</p></div><div class="share-actions"><button class="button primary" data-action="share-result">Share my score ↗</button><button class="button secondary" data-action="nav" data-page="create-custom">✍️ Create Your Own Wahala</button><button class="button ghost" data-action="replay">Try again ↻</button></div><h3 style="margin-top:30px">Your predictions</h3><ul class="mini-list">${state.playAnswers.map((ans,i)=>{const t=recipientQ(QS[i].q,ch);return `<li><span>${e(t.slice(0,55))}${t.length>55?'…':''}</span><b>${ans===ch.answers[i]?'✓ Nailed it':'✗ Missed'}</b></li>`}).join('')}</ul></section><aside class="side-panel"><h3>Now it's your turn 👀</h3><p>Think your people know you better? Write your own questions and put them to the test.</p><button class="button primary block" data-action="nav" data-page="create-custom">✍️ Create Your Own Wahala ↗</button><button class="button secondary block" data-action="nav" data-page="create" style="margin-top:9px">Try the Quick Challenge</button></aside></div></main>`}
const i=state.playStep, q=QS[i];return `<main class="shell page"><div class="page-header"><span class="kicker">${e(ch.owner_name)}'s challenge 🫵</span><h1>How well do you know <span class="accent">${e(ch.owner_name)}?</span></h1><p>Choose what you think they'd pick. Your score comes at the end, so no peeking!</p></div><div class="content-grid"><section class="panel"><div class="countbox"><span>QUESTION ${i+1} / ${total}</span><div class="progress"><div class="progress-fill" style="width:${(i)/total*100}%"></div></div></div><div class="question" style="border:0"><div class="question-index">Friendship test · No pressure 😌</div><h2 style="font-size:clamp(25px,4vw,36px);margin:12px 0 23px">${e(recipientQ(q.q,ch))}</h2><div class="options">${q.a.map((ans,j)=>`<button class="option" data-action="play-option" data-answer="${j}"><span class="letter">${String.fromCharCode(65+j)}</span>${e(recipientOpt(ans,ch))}</button>`).join('')}</div></div></section><aside class="side-panel"><span class="pill hot">🤝 Friendship under test</span><h3 style="margin-top:18px">${e(ch.owner_name)} is watching.</h3><p>Okay, maybe not literally. But their answers will decide your score.</p></aside></div></main>`}
function simulator(){const done=state.simDone, scene=SCENES[state.simIndex];return `<main class="shell page"><div class="page-header"><span class="kicker">Life simulator • Edition 001</span><h1>Can you survive <span class="accent">Naija?</span> 💸</h1><p>Salary entered your account. The month has other plans for you. Four decisions; one financial destiny.</p></div><div class="content-grid"><section class="panel"><div class="stat-grid"><div class="stat"><div class="value">${formatted(state.simMoney)}</div><div class="name">Bank balance</div></div><div class="stat"><div class="value">${Math.max(0,state.simPeace)}%</div><div class="name">Peace of mind</div></div><div class="stat"><div class="value">${Math.max(0,state.simStreet)}%</div><div class="name">Street cred</div></div></div>${done?`<div class="result-hero" style="padding-top:25px"><div class="result-emoji">${state.simMoney>=120000?'🏆':state.simMoney>=60000?'😅':'💀'}</div><h2>${state.simMoney>=120000?'Financial discipline legend':state.simMoney>=60000?'You survived. Somehow.':'Your account needs prayers'}</h2><p>You finished with <b style="color:var(--lime)">${formatted(state.simMoney)}</b>. ${state.simMoney>=120000?'You dodged most of the wahala!':state.simMoney>=60000?'Not broke, not exactly rich. We move.':'The next salary alert will be a rescue mission.'}</p></div><div class="share-actions"><button class="button primary" data-action="share-sim">Share my survival score ↗</button><button class="button secondary" data-action="restart-sim">Play again ↻</button></div>`:`<div class="countbox"><span>DAY ${state.simIndex+1} / ${SCENES.length}</span><div class="progress"><div class="progress-fill" style="width:${state.simIndex/SCENES.length*100}%"></div></div></div>${state.simResponse?`<div class="callout" style="margin-bottom:17px">${e(state.simResponse)}</div>`:''}<div class="sim-scene"><div class="big">${scene.emoji}</div><h2 style="font-size:26px">${e(scene.title)}</h2><p>${e(scene.text)}</p></div><div class="kicker" style="margin-bottom:10px">Make your move</div>${scene.choices.map((c,j)=>`<button class="sim-choice" data-action="sim-choice" data-answer="${j}">${e(c.label)} ↗</button>`).join('')}`}</section><aside class="side-panel"><h3>Welcome to adulthood 😭</h3><p>Your decisions affect three stats. There's no secret correct path; just consequences and a whole lot of wahala.</p><p>This mini-game uses fictional scenarios and is not financial advice.</p><div class="callout">Want to be more chaotic? Try a different decision on your next run.</div></aside></div></main>`}
function account(){const name=state.profile?.display_name || state.user?.user_metadata?.display_name || state.user?.email?.split('@')[0] || 'Guest';const act=state.cloudReady&&state.user?state.cloudActivities:getRecent();return `<main class="shell page"><div class="page-header"><span class="kicker">Your private corner 🛋️</span><h1>What's good, <span class="accent">${e(name)}?</span></h1><p>Your own WahalaVerse history. No public profile, no follower counts, no pressure.</p></div><div class="content-grid"><section class="panel"><div class="settingline"><div><strong>Account</strong><small>${state.user?e(state.user.email):'You’re cruising as a guest on this device'}</small></div><span class="pill">${state.user?'☁ Cloud':'⚡ Local'}</span></div><div class="settingline"><div><strong>Saved activities</strong><small>${state.user?'Synced to your account':'Saved only in this browser'}</small></div><b>${state.loadingAccount?'…':act.length}</b></div><h3 style="margin:27px 0 10px">Recent activity</h3>${state.loadingAccount?'<p>Loading your activity…</p>':act.length?act.slice(0,12).map(a=>`<div class="activity"><div><strong>${e(a.kind==='friendship_completed'?'🫂 Friendship challenge':a.kind==='assume_life_completed'?'🎭 Assume Their Life':'💸 Naija survival run')}</strong><small>${e(new Date(a.created_at).toLocaleString('en-NG',{dateStyle:'medium'}))}</small></div><span class="pill">${a.kind==='friendship_completed'?e(String(a.details?.score??0))+'/'+e(String(a.details?.total??7)):a.kind==='assume_life_completed'?e(String(a.details?.ending||'—')):formatted(Number(a.details?.balance||0))}</span></div>`).join(''):'<div class="empty">Nothing here yet. Go create some legendary wahala ✨</div>'}
${state.user?`<h3 style="margin:25px 0 12px">Challenges you've saved</h3>${state.cloudChallenges.length?state.cloudChallenges.map(ch=>`<div class="activity"><div><strong>${e(ch.title)}</strong><small>${e(new Date(ch.created_at).toLocaleDateString('en-NG'))}</small></div><button class="button small secondary" data-action="view-cloud" data-id="${e(ch.id)}">Open ↗</button></div>`).join(''):'<div class="empty">No saved challenges yet. Make your first one!</div>'}`:''}<div style="margin-top:25px"><button class="button primary" data-action="nav" data-page="create">Create a challenge ↗</button></div></section><aside class="side-panel"><h3>${state.user?'Your data stays yours 🔐':'Save your vibes ☁️'}</h3><p>${state.user?'Your email and private activity are not displayed publicly. People with your challenge link can see its public name and questions.':'Add your name and email to sign in. Your challenges and activities can then follow you across devices.'}</p>${state.user?'<button class="button secondary small" data-action="sign-out">Sign out</button>':`<button class="button primary block" data-action="auth" ${hasConfig?'':'disabled'}>${hasConfig?'Sign in with email ↗':'Sign-in available after setup'}</button>`}<p class="helper" style="margin-top:15px">${state.cloudReady?'☁ Supabase connected':'⚡ Prototype is running without a backend'}</p></aside></div></main>`}
function authDialog(){if(!state.authOpen)return '';return `<div class="dialog-backdrop" data-action="close-backdrop"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button class="close" aria-label="Close" data-action="close-auth">✕</button><div class="pill"><i></i> WahalaVerse beta</div><h2 id="auth-title">Join the cruise ☁️</h2><p>Save your challenges and game scores across devices. Just your name and email. No password wahala.</p>${!state.cloudReady?`<div class="notice">Demo mode is active. Real email sign-in becomes available after Supabase is configured.</div><button class="button block secondary" data-action="close-auth">Continue as guest</button>`:`<form id="auth-form"><div class="field"><label for="signup-name">What should we call you?</label><input id="signup-name" name="name" required maxlength="30" placeholder="e.g. Zee" autocomplete="nickname" value="${e(state.createName)}"></div><div class="field"><label for="signup-email">Email address</label><input id="signup-email" name="email" required type="email" maxlength="180" placeholder="you@example.com" autocomplete="email"></div><label style="display:flex;align-items:start;gap:10px;font-size:12px;color:var(--muted);margin:13px 0 20px"><input type="checkbox" name="adult" required style="margin-top:2px;accent-color:#d1fa49">I'm 18 or older. I understand that my name, email and saved activity will be stored for this account.</label><button class="button primary block" type="submit" id="auth-submit">Email me a sign-in link ↗</button></form><p class="dialog-note">We'll email you a one-time sign-in link. No marketing emails. <a href="privacy.html" target="_blank" rel="noopener" style="text-decoration:underline">How data is used</a>.</p>`}</div></div>`}
// --- Assume Their Life (causal life simulation) ----------------------------
function atlFmt(def,val){return def.fmt==='naira'?formatted(val):def.fmt==='pct'?val+'%':String(val)}
function atlDash(run){const pack=curPack();return `<div class="atl-dash">${Object.keys(pack.vars).map(k=>{const d=pack.vars[k],v=run.vars[k];return `<div class="atl-meter"><div class="atl-meter-top"><span>${d.emoji} ${e(d.label)}</span><b>${atlFmt(d,v)}</b></div>${d.fmt==='pct'?`<div class="atl-bar"><i style="width:${v}%"></i></div>`:''}</div>`}).join('')}</div>`}
function atlTicker(run){if(!run.fired.length)return '';return `<div class="atl-ticker">${run.fired.map(f=>`<div class="atl-tick">⏳ <b>Week ${f.firedWeek}:</b> ${e(f.note)}</div>`).join('')}</div>`}
function atlReckoning(r){const en=r.ending;const fmt=(d,v)=>d.fmt==='naira'?formatted(v):d.fmt==='pct'?v+'%':String(v);return `<main class="shell page"><div class="page-header"><span class="kicker">The Reckoning · after ${r.weeks} weeks</span><h1>Your year, <span class="accent">judged.</span></h1></div><div class="content-grid"><section class="panel"><div class="result-hero"><div class="result-emoji">${en.emoji}</div><h2>${e(en.title)}</h2><p>${e(en.blurb)}</p></div><h3 style="margin:24px 0 10px">Where you started → where you ended</h3><div class="atl-dash">${r.deltas.map(d=>{const ch=d.change,arrow=ch>0?'▲':ch<0?'▼':'■',cls=ch>0?'up':ch<0?'down':'';return `<div class="atl-meter"><div class="atl-meter-top"><span>${d.emoji} ${e(d.label)}</span><b class="${cls}">${fmt(d,d.start)} → ${fmt(d,d.end)} <small>${arrow}</small></b></div>${d.fmt==='pct'?`<div class="atl-bar"><i style="width:${d.end}%"></i></div>`:''}</div>`}).join('')}</div>${r.surprises.length?`<h3 style="margin:24px 0 10px">The consequences that caught up with you ⏳</h3><ul class="mini-list">${r.surprises.map(s=>`<li><span>Week ${s.week}: ${e(s.note)}</span></li>`).join('')}</ul>`:''}<h3 style="margin:24px 0 10px">The decisions that mattered</h3><ul class="mini-list">${r.pivotal.map(p=>`<li><span><b>Week ${p.week}:</b> ${e(p.label)}<em style="color:#9b95b0;display:block;font-size:12px;margin-top:3px">${e(p.why)}</em></span></li>`).join('')}</ul><div class="share-actions" style="margin-top:22px"><button class="button primary" data-action="atl-share">Share my result ↗</button><button class="button secondary" data-action="atl-replay">Replay this life ↻</button></div></section><aside class="side-panel"><h3>Same start, different story 🎭</h3><p>Run it again and make different calls early — the whole year unfolds differently. That's the point: consequences, not trivia.</p><button class="button block secondary" data-action="atl-pickreset">Assume another life ↗</button></aside></div></main>`}
function atlView(){if(!ATL||!ATL_PACKS.length)return `<main class="shell page"><div class="panel"><h2>Loading simulation…</h2></div></main>`;
  // Role picker — choose which life to assume.
  if(!state.atlRole||!curPack())return `<main class="shell page"><div class="page-header"><span class="kicker">Assume Their Life 🎭</span><h1>Assume <span class="accent">another life.</span></h1><p>Step into a role, make real decisions, and live with the consequences over a year. Not a quiz — every choice trades something, and the game remembers.</p></div><section class="section"><div class="cards">${ATL_PACKS.map(([key,p])=>`<article class="experience"><div class="eyebrow">${key==='afrobeats'?'Extra role':'Core role'}</div><h3>${e(p.title)}</h3><p>${e(p.role)}.</p><p style="color:var(--muted);font-size:13px">${e(p.briefing.hook)}</p><button class="button small primary" data-action="atl-pick" data-role="${e(key)}">Assume this life ↗</button></article>`).join('')}</div></section></main>`;
  const pack=curPack(),run=state.atlRun;
  if(!run){const b=pack.briefing;return `<main class="shell page"><div class="page-header"><span class="kicker">Assume Their Life · ${e(pack.title)}</span><h1>${e(pack.title)}: <span class="accent">${e(pack.role)}</span></h1><p>${e(b.hook)}</p></div><div class="content-grid"><section class="panel"><div class="atl-brief"><p><b>✅ You control:</b> ${e(b.control)}</p><p><b>🚫 You don't:</b> ${e(b.cannot)}</p><p><b>⏳ Starting tension:</b> ${e(b.tension)}</p><p><b>🎯 The goal:</b> ${e(b.goal)}</p></div><div class="atl-note">Fictional simulation — no real person is depicted. Your choices cause immediate <i>and</i> delayed consequences over a year; the ending explains why.</div><button class="button primary block" data-action="atl-start">Start this life ↗</button><button class="button ghost small block" data-action="atl-pickreset" style="margin-top:8px">← Choose a different life</button></section><aside class="side-panel"><span class="pill hot">🎭 Not a quiz</span><h3 style="margin-top:18px">Decisions, not trivia.</h3><p>There's no secret correct answer. Every move trades something — money, control, relationships, your wellbeing — and the game remembers.</p></aside></div></main>`}
  if(ATL.isEnded(run))return atlReckoning(ATL.reckoning(pack,run));
  const ev=ATL.currentEvent(pack,run);return `<main class="shell page"><div class="page-header"><span class="kicker">Week ${run.week} / ${pack.horizonWeeks} · ${e(ev.arc||'')}</span><h1 style="font-size:clamp(26px,5vw,40px)">${e(ev.title)}</h1></div><div class="content-grid"><section class="panel">${atlDash(run)}${atlTicker(run)}<div class="sim-scene" style="margin-top:6px"><p style="font-size:17px;line-height:1.5">${e(ev.body)}</p></div>${state.atlReaction?`<div class="callout" style="margin:14px 0">${e(state.atlReaction)}</div>`:''}<div class="kicker" style="margin:16px 0 10px">What do you do?</div>${ev.choices.map(c=>`<button class="sim-choice" data-action="atl-choice" data-choice="${e(c.id)}">${e(c.label)} ↗</button>`).join('')}</section><aside class="side-panel"><h3>${e(pack.title)}</h3><p>${run.history.length} decision${run.history.length===1?'':'s'} made. Your choices are piling up — and the game remembers.</p>${run.fired.length?`<div class="callout"><b>Consequences landed:</b> ${run.fired.length}</div>`:''}<p class="helper" style="margin-top:14px">Fictional simulation. Not financial, legal or career advice 😌</p></aside></div></main>`}
function render(){const pages={home,create,'create-custom':createCustom,play:player,sim:simulator,atl:atlView,account};root.innerHTML=header()+(pages[state.page]||home)()+footer()+bottomNav()+authDialog();document.title=state.page==='home'?'WahalaVerse — Catch cruise, not feelings.':state.page==='create'?'Create a challenge — WahalaVerse':state.page==='create-custom'?'Create Your Own Wahala — WahalaVerse':state.page==='play'?'Friendship challenge — WahalaVerse':state.page==='sim'?'Survive Naija — WahalaVerse':state.page==='atl'?'Assume Their Life — WahalaVerse':'My corner — WahalaVerse'}
function updateCreateButtons(){document.querySelectorAll('[data-action="create-option"]').forEach(btn=>{const s=state.createAnswers[Number(btn.dataset.q)]===Number(btn.dataset.answer);btn.classList.toggle('selected',s);btn.setAttribute('aria-pressed',String(s))});const count=state.createAnswers.filter(x=>x!==null).length;const value=document.getElementById('answered-count'),progress=document.getElementById('create-progress');if(value)value.textContent=count;if(progress)progress.style.width=count/Q.length*100+'%'}
async function newChallenge(){if(state.creating)return;const name=titleCase(document.getElementById('creator-name')?.value||state.createName);state.createName=name;if(name.length<2){toast('Enter a name with at least 2 characters ✍️');return}if(state.createAnswers.some(x=>x===null)){toast('Answer all 7 questions first 👀');return}const ch={owner_name:name,title:`How well do you know ${name}?`,answers:state.createAnswers.map(Number),template_version:1};let link='';let cloud=false;state.creating=true;const btn=document.querySelector('[data-action="create-save"]');if(btn){btn.disabled=true;btn.textContent='Generating…'}try{if(state.user&&state.supabase){try{const {data,error}=await state.supabase.from('challenges').insert({owner_id:state.user.id,owner_name:name,title:ch.title,answers:ch.answers,template_version:1}).select('id').single();if(error)throw error;link=urlFor({c:data.id});cloud=true;await refreshAccount()}catch(err){console.warn('Save to cloud failed:',err);toast('Cloud save failed. Created a shareable guest link instead.')}}if(!link)link=urlFor({guest:encodeChallenge(ch)});state.createdUrl=link;state.createdCloud=cloud;state.createdKind='quick'}finally{state.creating=false}render();window.scrollTo({top:0,behavior:'instant'})}
async function generateCustom(){if(state.creating)return;const name=titleCase(state.customName);state.customName=name;const ch={owner_name:name,title:`How well do you know ${name}?`,questions:state.customQuestions.map(q=>({q:(q.q||'').trim(),a:(q.a||[]).map(o=>(o||'').trim())})),answers:state.customQuestions.map(q=>q.answer)};const v=C.validateCustomChallenge(ch);if(!v.ok){toast('Finish every question + options and mark an answer ✍️');return}state.creating=true;render();try{const token=await C.encodeCustomChallenge(ch);state.createdUrl=urlFor({guest:token});state.createdKind='custom';state.createdCloud=false;state.customPreview=false;clearCcDraft();state.ccRecovered=false}catch(err){if(err&&err.code==='too-long'){state.customPreview=false;toast('Your challenge is a bit long to fit in a share link — shorten some questions or options.')}else{toast('Could not generate the link. Please try again.')}}finally{state.creating=false}render();window.scrollTo({top:0,behavior:'instant'})}
async function loadChallenge(fromUrl=true){state.page='play';
  // Cloud (?c=) link opened before the Supabase SDK has initialized: show a
  // loading state and let initCloud re-call this once ready — don't flash a
  // false "link broken" error. If cloud isn't configured at all, say so plainly.
  if(fromUrl&&qs.get('c')&&!state.supabase){state.challenge=null;state.playAnswers=[];state.playStep=0;state.playSaved=false;if(hasConfig){state.loading=true;state.cloudLinkUnavailable=false}else{state.loading=false;state.cloudLinkUnavailable=true}render();return}
  state.challenge=null;state.loading=true;state.cloudLinkUnavailable=false;state.playAnswers=[];state.playStep=0;state.playSaved=false;render();try{let ch;if(fromUrl&&qs.get('c')){const {data,error}=await state.supabase.from('challenges').select('id,owner_name,title,answers,template_version').eq('id',qs.get('c')).single();if(error)throw error;ch={...data,type:'cloud'}}else if(fromUrl&&qs.get('guest')){ch=await decodeChallenge(qs.get('guest'))}else{ch=DEMO}state.challenge=ch}catch(err){console.warn('Challenge could not load:',err);state.challenge=null}finally{state.loading=false;render()}}
function sample(){history.pushState({},'',location.pathname+'?sample=1');window.scrollTo({top:0,behavior:'instant'});void loadChallenge()}
function challengeTotal(){return state.challenge?.questions?.length||Q.length}
function finishPlay(){const total=challengeTotal();state.playStep=total;const score=C.scoreQuiz(state.playAnswers,state.challenge.answers);if(!state.playSaved){state.playSaved=true;saveActivity('friendship_completed',{score,total,challenge_id:state.challenge.type==='cloud'?state.challenge.id:null})}render()}
function restartSim(){state.simIndex=0;state.simMoney=SIM_START.money;state.simPeace=SIM_START.peace;state.simStreet=SIM_START.street;state.simResponse='';state.simDone=false;render()}
function simChoose(i){if(state.simDone)return;const c=SCENES[state.simIndex]?.choices?.[i];if(!c)return;const next=C.applySimChoice({money:state.simMoney,peace:state.simPeace,street:state.simStreet},c);state.simMoney=next.money;state.simPeace=next.peace;state.simStreet=next.street;state.simResponse=c.reply;state.simIndex+=1;if(state.simIndex>=SCENES.length){state.simDone=true;saveActivity('simulator_completed',{balance:state.simMoney,peace:state.simPeace,street:state.simStreet})}render()}
// Per-browser-session guest id: used to attribute unowned (guest) activities to
// THIS session only, so a previous session's or another person's guest history
// on the same browser is never silently synced to a signed-in account.
function initGuestSession(){let s;try{s=sessionStorage.getItem('wv_guest_session')}catch{/* private mode */}if(!s){s=id();try{sessionStorage.setItem('wv_guest_session',s)}catch{/* private mode */}}return s}
const guestSessionId=initGuestSession();
// Account state machine (profile/activity/challenge sync) lives in account.js so
// it can be driven by deterministic tests with mocked auth/db. It mutates the
// shared `state` object through injected collaborators.
const accountMgr=WahalaAccount.create({state,core:C,storage:{getRecent,setRecent},getSessionId:()=>guestSessionId,getPendingName:()=>{try{return localStorage.getItem('wv_pending_name')}catch{return null}},render});
const syncActivities=()=>accountMgr.syncActivities();
const refreshAccount=()=>accountMgr.refreshAccount();
const ensureProfile=()=>accountMgr.ensureProfile();
function saveActivity(kind,details){const data=getRecent();const entry={id:id(),kind,details,created_at:new Date().toISOString(),synced:false,owner:state.user?.id||null};if(!entry.owner)entry.session=guestSessionId;data.unshift(entry);setRecent(data);void syncActivities()}
async function initCloud(){if(!hasConfig){render();return}try{const sdk=await import('https://esm.sh/@supabase/supabase-js@2');state.supabase=sdk.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey);state.cloudReady=true;const {data:{session}}=await state.supabase.auth.getSession();state.user=session?.user||null;state.supabase.auth.onAuthStateChange((_event,session)=>{const oldId=state.user?.id||null;state.user=session?.user||null;const newId=state.user?.id||null;if(newId!==oldId){state.authEpoch++;accountMgr.clearAccountState();}if(state.user&&newId!==oldId)Promise.resolve().then(ensureProfile);else render()});render();if(state.user)void ensureProfile();if(qs.has('c')&&state.page==='play')void loadChallenge()}catch(err){console.error('Cloud initialization error:',err);state.cloudReady=false;if(qs.has('c')&&state.page==='play'){state.loading=false;state.challenge=null}render()}}
async function requestSignIn(form){if(!state.supabase){toast('Set up Supabase first to enable real accounts');return}const data=new FormData(form);const name=titleCase(data.get('name'));const email=String(data.get('email')||'').trim();if(name.length<2||!email.includes('@')||!data.get('adult')){toast('Add your details and confirm 18+');return}const submit=form.querySelector('button[type=submit]');submit.disabled=true;submit.textContent='Sending your link…';try{localStorage.setItem('wv_pending_name',name);const {error}=await state.supabase.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname,data:{display_name:name}}});if(error)throw error;state.authOpen=false;render();toast('Check your email for a sign-in link 📩')}catch(err){toast(err.message||'Could not send the sign-in link');submit.disabled=false;submit.textContent='Email me a sign-in link ↗'}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied! Send it to your people 📋')}catch{const tmp=document.createElement('textarea');tmp.value=text;tmp.style.position='fixed';tmp.style.top='-2000px';document.body.appendChild(tmp);tmp.select();const ok=document.execCommand('copy');tmp.remove();toast(ok?'Copied! Send it to your people 📋':'Copy the link from the box above')}}
function shareLink(link,title,text){if(navigator.share){navigator.share({title,text,url:link}).catch(err=>{if(err.name!=='AbortError')void copy(link)})}else void copy(text+' '+link)}
async function interpretUrl(){qs=new URLSearchParams(location.search);const page=qs.get('page');if(qs.has('guest')||qs.has('c')||qs.has('sample')){state.page='play';await loadChallenge()}else{state.page=['home','create','create-custom','sim','atl','account'].includes(page)?page:'home';if(state.page==='create-custom')ensureCustomDraft();render();if(state.page==='account'&&state.user)void refreshAccount()}}
root.addEventListener('click',async ev=>{const t=ev.target.closest('[data-action]');if(!t)return;const action=t.dataset.action;
if(t.tagName==='A')ev.preventDefault();
switch(action){
case 'nav':{const p=t.dataset.page||'home';if(p==='create-custom'){state.createdUrl='';state.createdKind='quick';state.customPreview=false;ensureCustomDraft()}nav(p);if(state.page==='account'&&state.user)void refreshAccount();break}
case 'auth':openAuth();break;
case 'close-auth':closeAuth();break;
case 'close-backdrop':if(ev.target===t)closeAuth();break;
case 'sample':sample();break;
case 'create-option':state.createAnswers[Number(t.dataset.q)]=Number(t.dataset.answer);updateCreateButtons();break;
case 'create-save':await newChallenge();break;
case 'reset-create':if(state.createdKind==='custom'){clearCcDraft();state.createdUrl='';state.customQuestions=blankCustom();state.customName='';state.customPreview=false;state.ccRecovered=false}else{state.createdUrl='';state.createAnswers=Array(Q.length).fill(null)}render();break;
case 'cc-add-q':if(state.customQuestions.length<C.CUSTOM_LIMITS.maxQuestions)state.customQuestions.push({q:'',a:['',''],answer:null});scheduleCcSave();render();break;
case 'cc-del-q':state.customQuestions.splice(Number(t.dataset.qi),1);scheduleCcSave();render();break;
case 'cc-add-opt':{const q=state.customQuestions[Number(t.dataset.qi)];if(q&&q.a.length<C.CUSTOM_LIMITS.maxOptions)q.a.push('');scheduleCcSave();render();break}
case 'cc-del-opt':{const q=state.customQuestions[Number(t.dataset.qi)],oi=Number(t.dataset.oi);if(q&&q.a.length>C.CUSTOM_LIMITS.minOptions){q.a.splice(oi,1);if(q.answer===oi)q.answer=null;else if(q.answer>oi)q.answer-=1}scheduleCcSave();render();break}
case 'cc-answer':{const q=state.customQuestions[Number(t.dataset.qi)];if(q)q.answer=Number(t.dataset.oi);scheduleCcSave();render();break}
case 'cc-usename':{const q=state.customQuestions[Number(t.dataset.qi)];if(q){const before=q.q||'';q.q=C.resolveToName(before).slice(0,C.CUSTOM_LIMITS.questionLen);q.pAck=false;scheduleCcSave();render();if(q.q===before)toast('No simple word to swap — edit the wording to use your name ✍️');else if(C.hasAmbiguousPerspective(q.q))toast('Swapped what I safely could — please edit the rest ✍️')}break}
case 'cc-ack':{const q=state.customQuestions[Number(t.dataset.qi)];if(q){q.pAck=true;scheduleCcSave();render()}break}
case 'cc-discard-draft':clearCcDraft();state.customQuestions=blankCustom();state.customName='';state.customPreview=false;state.ccRecovered=false;render();break;
case 'cc-dismiss-recovered':state.ccRecovered=false;render();break;
case 'cc-preview':if(ccReady().allReady){state.customPreview=true;render();window.scrollTo({top:0,behavior:'instant'})}else{toast('Add your name + finish every question first ✍️')}break;
case 'cc-back-edit':state.customPreview=false;render();break;
case 'cc-generate':await generateCustom();break;
case 'copy-link':void copy(state.createdUrl);break;
case 'share-link':shareLink(state.createdUrl,'Predict My Wahala','You think you know me? 😭 Score at least 5/7 on my WahalaVerse challenge:');break;
case 'test-link':location.href=state.createdUrl;break;
case 'play-option':state.playAnswers.push(Number(t.dataset.answer));state.playStep+=1;if(state.playStep>=challengeTotal())finishPlay();else render();break;
case 'replay':state.playAnswers=[];state.playStep=0;state.playSaved=false;render();break;
case 'share-result':{const total=challengeTotal();const score=C.scoreQuiz(state.playAnswers,state.challenge.answers);const url=location.href;shareLink(url,'My WahalaVerse score',`I got ${score}/${total} on ${state.challenge.owner_name}'s WahalaVerse challenge 😂 Can you beat me?`);break}
case 'sim-choice':simChoose(Number(t.dataset.answer));break;
case 'restart-sim':restartSim();break;
case 'atl-pick':state.atlRole=t.dataset.role;state.atlRun=null;state.atlReaction='';state.atlSaved=false;render();window.scrollTo({top:0,behavior:'instant'});break;
case 'atl-pickreset':state.atlRole=null;state.atlRun=null;state.atlReaction='';state.atlSaved=false;render();window.scrollTo({top:0,behavior:'instant'});break;
case 'atl-start':{const pack=curPack();if(!pack)break;state.atlRun=ATL.createRun(pack);state.atlReaction='';state.atlSaved=false;render();window.scrollTo({top:0,behavior:'instant'});break}
case 'atl-choice':{const pack=curPack();if(!pack||!state.atlRun)break;const cur=ATL.currentEvent(pack,state.atlRun);const c=cur?.choices?.find(x=>x.id===t.dataset.choice);state.atlReaction=c?.reaction||'';ATL.choose(pack,state.atlRun,t.dataset.choice);if(ATL.isEnded(state.atlRun)){state.atlReaction='';if(!state.atlSaved){state.atlSaved=true;saveActivity('assume_life_completed',{role:pack.role,ending:state.atlRun.ending?.title||''})}}render();window.scrollTo({top:0,behavior:'instant'});break}
case 'atl-replay':state.atlRun=null;state.atlReaction='';state.atlSaved=false;render();break;
case 'atl-share':{const url=location.origin+location.pathname+'?page=atl';shareLink(url,state.atlRun?.ending?.title||'Assume Their Life',state.atlRun?.ending?.share||'I played WahalaVerse: Assume Their Life 🎭');break}
case 'share-sim':shareLink(location.origin+location.pathname+'?page=sim','Survive Naija',`I survived Survive Naija with ${formatted(state.simMoney)} left. Can you do better? 😂`);break;
case 'view-cloud':location.href=urlFor({c:t.dataset.id});break;
case 'sign-out':if(state.supabase){state.authEpoch++;state.user=null;accountMgr.clearAccountState();try{localStorage.removeItem('wv_activity')}catch{/* private mode */}await state.supabase.auth.signOut();render();toast('Signed out successfully')}break;
}});
root.addEventListener('submit',ev=>{if(ev.target.id==='auth-form'){ev.preventDefault();void requestSignIn(ev.target)}});
root.addEventListener('input',ev=>{const t=ev.target;if(t.id==='creator-name'){state.createName=t.value;return}const cc=t.dataset&&t.dataset.cc;if(!cc)return;if(cc==='name'){state.customName=t.value}else if(cc==='q'){const q=state.customQuestions[Number(t.dataset.qi)];if(q)q.q=t.value}else if(cc==='o'){const q=state.customQuestions[Number(t.dataset.qi)];if(q)q.a[Number(t.dataset.oi)]=t.value}
  // Live, in-place perspective nudge for the edited question — no full re-render, so the
  // creator never loses focus/caret while typing.
  if(cc==='q'){const q=state.customQuestions[Number(t.dataset.qi)];if(q)q.pAck=false;const sug=t.closest&&t.closest('.question')?.querySelector('.cc-suggest');if(sug)sug.style.display=C.hasAmbiguousPerspective(t.value)?'block':'none'}
  scheduleCcSave()});
function dialogFocusable(){const d=document.querySelector('.dialog');if(!d)return[];return Array.from(d.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')).filter(el=>!el.disabled&&el.offsetParent!==null)}
function openAuth(){state.lastFocus=document.activeElement;state.authOpen=true;render();const f=dialogFocusable();(f.find(el=>el.tagName==='INPUT')||f[0])?.focus()}
function closeAuth(){state.authOpen=false;render();try{state.lastFocus?.focus?.()}catch{/* element gone */}state.lastFocus=null}
document.addEventListener('keydown',ev=>{if(!state.authOpen)return;if(ev.key==='Escape'){closeAuth();return}if(ev.key==='Tab'){const f=dialogFocusable();if(!f.length)return;const first=f[0],last=f[f.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}});
window.addEventListener('popstate',()=>{state.createdUrl='';void interpretUrl()});
// Flush the latest CYOW draft on immediate reload/close/tab-hide, in case the
// debounced save hasn't fired yet. Suppressed right after discard/generation.
window.addEventListener('pagehide',()=>{if(!ccSuppressSave)saveCcDraftNow()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&!ccSuppressSave)saveCcDraftNow()});
void interpretUrl();void initCloud();
})();
